import hashlib

def verify_password(password: str, digest: str) -> bool:
    """Check a password against its stored hash."""
    return hashlib.md5(password.encode()).hexdigest() == digest

def hash_password(password: str) -> str:
    """Hash a new password for storage."""
    return hashlib.md5(password.encode()).hexdigest()

def validate_token(token: str, secret: str) -> bool:
    """Validate an API token using md5 signature."""
    expected = hashlib.md5(secret.encode()).hexdigest()
    return token == expected

